/**
 * EVIDENCE BASE: a curated, hand-written reference set of well-known published studies, books and models in
 * psychology and psychiatry that the NPC minds are built on. It is NOT a scrape, a database export or an exhaustive
 * literature review. Every entry is something the author is confident exists and states the finding in a deliberately
 * conservative, one-line form; where a detail is uncertain it is left out, and findings that later replicated poorly
 * or are debated carry the `contested` flag (the game models them anyway, but honestly labelled).
 *
 * Each entry names the model parameter or behaviour it drives in this codebase (`drives` is an identifier that really
 * exists in src/mind or the AI; tests/mind-clinical.test.ts checks that, so the catalogue cannot silently drift).
 * The game is a parody life sim: these are the real-science inspirations for simplified mechanics, not clinical tools.
 *
 * confidence: 'landmark' = foundational and widely cited; 'well-replicated' = robust across studies/meta-analyses;
 * 'contested' = influential but debated or with mixed replication.
 */
export type Confidence = "landmark" | "well-replicated" | "contested";
export interface Evidence {
  id: string;
  /** authors, year, journal or book */
  cite: string;
  /** the finding in one line */
  finding: string;
  /** identifier in the codebase this informs, then a short note on how */
  drives: string;
  confidence: Confidence;
  tags: string[];
}

const L: Confidence = "landmark", W: Confidence = "well-replicated", C: Confidence = "contested";
const E = (id: string, cite: string, finding: string, drives: string, confidence: Confidence, tags: string): Evidence => ({ id, cite, finding, drives, confidence, tags: tags.split(" ") });

