/** Case-insensitive search over id, citation, finding, driver and tags. */
export function searchEvidence(query: string): Evidence[] {
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
  return EVIDENCE.filter((e) => { const hay = (e.id + " " + e.cite + " " + e.finding + " " + e.drives + " " + e.tags.join(" ")).toLowerCase(); return terms.every((t) => hay.includes(t)); });
}
/** Studies informing a given code identifier (the `drives` field starts with it). */
export function evidenceFor(identifier: string): Evidence[] { return EVIDENCE.filter((e) => e.drives.split(/[^A-Za-z0-9_]/)[0] === identifier); }
